+        dimension.usageEntitlement !== null
+    ) {
+        return 'tiers cannot be combined with usageEntitlement';
+    }
+    if (dimension.consumptionPrice !== undefined && dimension.consumptionPrice !== null) {
+        return 'tiers cannot be combined with consumptionPrice';
+    }
+    if (dimension.overageAllowed === overageAllowedEnum.true) {
