+    }
+
+    const usageIncrement = Number(dimension.usageIncrement);
+    if (!Number.isFinite(usageIncrement) || usageIncrement <= 0) {
+        return 'usageIncrement must be greater than zero when tiers are set';
+    }
+
+    const sortedTiers = [...tiers].sort((left, right) => Number(left.tierPosition) - Number(right.tierPosition));
+    const positions = new Set<string>();
+    let previousBound = 0;
+
